CREATE proc [dbo].[GetDeliveryCustomer] @Type as nvarchar(50),@Find as nvarchar(max),@group_id as int as if @Type = 'All' begin select c.id,(c.Customer_name) as [Name],c.address as Address,c.tel_no as TellNo,c.cell_no as CellNo,c.Address2,g.customer_group_name as 'Customer Group' from customerpos_ c inner join customer_group g on  c.customer_group_id = g.customer_group_id where c.Active = 1 end  else begin select id,(c.Customer_name) as [Name],c.address as Address,c.tel_no as TellNo,c.cell_no as CellNo ,c.Address2,g.customer_group_name as 'Customer Group' from customerpos_ c inner join customer_group g on c.customer_group_id = g.customer_group_id where c.Active = 1 and c.customer_group_id = @group_id end